
$(function () {
  var wrapper = $("#main-wrapper");
  var sidebar = document.getElementById("main-sidebar");
  var desktop = window.matchMedia("(min-width: 1200px)");
  var storageKey = "regulai.sidebar.hidden";
  var desktopHidden = false;
  var mobileOpen = false;
  try {
    desktopHidden = window.localStorage.getItem(storageKey) === "true";
  } catch (error) {
    // Storage is optional; the toggle still works without persistence.
  }
  function renderSidebar() {
    var visible = desktop.matches ? !desktopHidden : mobileOpen;
    wrapper.attr("data-sidebartype", desktop.matches ? "full" : "mini-sidebar");
    wrapper.toggleClass("mini-sidebar", !desktop.matches);
    wrapper.toggleClass("sidebar-hidden", desktop.matches && desktopHidden);
    wrapper.toggleClass("show-sidebar", !desktop.matches && mobileOpen);
    if (sidebar) {
      if (!visible && sidebar.contains(document.activeElement)) {
        document.getElementById("headerCollapse").focus();
      }
      sidebar.inert = !visible;
      sidebar.setAttribute("aria-hidden", String(!visible));
    }
    $(".sidebartoggler").attr("aria-expanded", String(visible));
    $("#headerCollapse").attr({
      "aria-label": visible ? "Ocultar menú lateral" : "Mostrar menú lateral",
      title: visible ? "Ocultar menú lateral" : "Mostrar menú lateral"
    });
  }
  $(".sidebartoggler").on("click", function () {
    if (desktop.matches) {
      desktopHidden = !desktopHidden;
      try {
        window.localStorage.setItem(storageKey, String(desktopHidden));
      } catch (error) {
        // Keep this page usable if browser storage is unavailable.
      }
    } else {
      mobileOpen = !mobileOpen;
    }
    renderSidebar();
  });
  desktop.addEventListener("change", function () {
    mobileOpen = false;
    renderSidebar();
  });
  renderSidebar();
});
